#include <bits/stdc++.h>
using namespace std;

const int LOG = 20;
int n, q;
vector<int> adj[200005];
int up_[200005][LOG];
int depth_[200005];

void dfs(int v, int p) {
    up_[v][0] = p;
    for (int j = 1; j < LOG; j++)
        up_[v][j] = up_[up_[v][j-1]][j-1];
    for (int c : adj[v]) {
        if (c != p) {
            depth_[c] = depth_[v] + 1;
            dfs(c, v);
        }
    }
}

int lca(int u, int v) {
    if (depth_[u] < depth_[v]) swap(u, v);
    int diff = depth_[u] - depth_[v];
    for (int j = 0; j < LOG; j++)
        if ((diff >> j) & 1) u = up_[u][j];
    if (u == v) return u;
    for (int j = LOG - 1; j >= 0; j--) {
        if (up_[u][j] != up_[v][j]) {
            u = up_[u][j];
            v = up_[v][j];
        }
    }
    return up_[u][0];
}

